import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#14141a' }],
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItems = items.filter((i) => i.role === 'caption');

  const root = new Group();
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---- STAGE BACKDROP (vertical gradient) ----
  const gStops = colors.gradientStops ?? [{ at: 0, hex: colors.background }, { at: 1, hex: colors.surface }];
  const cTop = new Color(gStops[gStops.length - 1].hex);
  const cBot = new Color(gStops[0].hex);
  const bgMat = new MeshBasicNodeMaterial();
  const vY = uv().y;
  bgMat.colorNode = mix(
    vec3(cBot.r, cBot.g, cBot.b),
    vec3(cTop.r, cTop.g, cTop.b),
    smoothstep(0.0, 1.0, vY)
  );
  const backdrop = new Mesh(new PlaneGeometry(7, 6), bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdrop.geometry, bgMat);

  // ---- LIGHTS (node-local rim/accent; scene provides ambient+key) ----
  const fill = new AmbientLight(0xffffff, 0.35);
  root.add(fill);

  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(-2.5, 3, 4);
  root.add(key);

  const accentColor = new Color(colors.accent);
  const rim = new DirectionalLight(accentColor.getHex(), 0.9);
  rim.position.set(3, -1, 3);
  root.add(rim);

  // ---- IMAGE COLUMN ----
  const column = new Group();
  column.position.x = 0.9;
  root.add(column);

  const PLATE_W = 1.9;
  const PLATE_H = 1.2;
  const PITCH = 1.5;
  const LOOP = 9.0;
  const COUNT = 6;

  const plates = [];
  const plateMats = [];

  // shared texture (single asset; distinct crops via uv offset)
  let sharedTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    sharedTex = tex;
    plateMats.forEach((m) => { m.map = tex; m.needsUpdate = true; });
  }).catch(() => {});

  const paperCol = new Color(colors.paper);

  for (let i = 0; i < COUNT; i++) {
    const plate = new Group();

    // bevel frame (machined ink)
    const bevelMat = new MeshStandardNodeMaterial();
    bevelMat.color = new Color(colors.ink);
    bevelMat.roughness = 0.5;
    bevelMat.metalness = 0.5;
    bevelMat.clearcoat = 0.1;
    const bevel = new Mesh(new BoxGeometry(PLATE_W + 0.06, PLATE_H + 0.06, 0.06), bevelMat);
    bevel.position.z = -0.02;
    plate.add(bevel);
    disposables.push(bevel.geometry, bevelMat);

    // photo plate
    const mat = new MeshStandardNodeMaterial();
    mat.color = new Color('#5a5a62'); // mid tone until texture loads (no near-black void)
    mat.roughness = 0.6;
    mat.metalness = 0.1;
    mat.clearcoat = 0.1;
    plateMats.push(mat);
    const mesh = new Mesh(new PlaneGeometry(PLATE_W, PLATE_H), mat);
    mesh.position.z = 0.02;
    plate.add(mesh);
    disposables.push(mesh.geometry, mat);

    // accent strip (left edge, focused indicator)
    const stripMat = new MeshStandardNodeMaterial();
    stripMat.color = accentColor.clone();
    stripMat.emissive = accentColor.clone();
    stripMat.emissiveIntensity = 1.4;
    stripMat.roughness = 0.5;
    stripMat.metalness = 0.0;
    const strip = new Mesh(new PlaneGeometry(0.03, PLATE_H), stripMat);
    strip.position.set(-PLATE_W / 2 - 0.02, 0, 0.03);
    strip.visible = false;
    plate.add(strip);
    disposables.push(strip.geometry, stripMat);

    // caption at x=-1.6 (relative to column, so world adjust)
    const capText = captionItems[i % captionItems.length];
    const capLabel = capText ? capText.text : 'PLATE';
    const cap = ctx.fontAtlas.createText(capLabel, {
      fontSize: 34,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 3,
    });
    cap.scale.setScalar(0.006);
    cap.position.set(-PLATE_W / 2 - 2.5, -PLATE_H / 2 + 0.1, 0.05);
    plate.add(cap);

    plate.position.y = i * PITCH;
    plate.userData.strip = strip;
    plate.userData.mesh = mesh;
    plate.userData.baseIndex = i;

    column.add(plate);
    plates.push(plate);
  }

  // ---- HEADLINE header pinned at [-1.6, 1.9, 0] ----
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 520,
    });
    headline.scale.setScalar(0.006);
    headline.position.set(-3.0, 1.9, 0.1);
    root.add(headline);

    const hTl = gsap.timeline();
    headline.position.y = 1.5;
    hTl.to(headline.position, { y: 1.9, duration: 0.7, ease: 'power3.out' });
    timelines.push(hTl);
  }

  // ---- SCROLL STATE (loop column + focus) ----
  const scrollState = { offset: 0, target: 0 };

  function wrapY(y) {
    let w = y % LOOP;
    if (w > LOOP / 2) w -= LOOP;
    if (w < -LOOP / 2) w += LOOP;
    return w;
  }

  function updatePlates() {
    let focused = null;
    let focusDist = Infinity;
    for (const p of plates) {
      const raw = p.userData.baseIndex * PITCH + scrollState.offset;
      const y = wrapY(raw);
      p.position.y = y;
      const d = Math.abs(y);
      if (d < focusDist) { focusDist = d; focused = p; }
    }
    for (const p of plates) {
      const isFocus = p === focused;
      const targetScale = isFocus ? 1.06 : 1.0;
      gsap.to(p.scale, { x: targetScale, y: targetScale, z: targetScale, duration: 0.35, ease: 'power2.out', overwrite: 'auto' });
      p.userData.strip.visible = isFocus;
    }
  }
  updatePlates();

  // idle breathing on column (single slow transform)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(column.position, { y: '+=0.04', duration: 4, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---- CINEMATIC PRIMITIVES ----
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---- SCROLL HANDLER ----
  root.userData.handlers = {
    scroll: (e) => {
      const delta = (e && typeof e.delta === 'number') ? e.delta : (e && e.deltaY ? e.deltaY * 0.001 : 0);
      scrollState.target += delta * PITCH;
      gsap.to(scrollState, {
        offset: scrollState.target,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto',
        onUpdate: updatePlates,
      });
    },
  };

  // ---- ENTRANCE ----
  const enterTl = gsap.timeline();
  plates.forEach((p, i) => {
    p.userData.mesh.material.opacity = 1;
    const startY = p.position.y;
    p.position.y = startY + 0.4;
    enterTl.to(p.position, { y: startY, duration: 0.7, ease: 'power3.out' }, i * 0.08);
  });
  timelines.push(enterTl);

  // ---- CLEANUP ----
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(scrollState);
    plates.forEach((p) => { gsap.killTweensOf(p.scale); gsap.killTweensOf(p.position); });
    gsap.killTweensOf(column.position);
    primHandles.forEach((h) => { try { h.cleanup && h.cleanup(); } catch (e) {} });
    disposables.forEach((d) => { try { d.dispose && d.dispose(); } catch (e) {} });
    if (sharedTex) { try { sharedTex.dispose(); } catch (e) {} }
  };

  return root;
}
